           ,[ap_id]
           ,[paiddate]
           ,[remark]
           ,[amount]
           ,[inputter]
           ,[created_at])
		   VALUES (@vsysdoc,@vbranchcode,@vap_id,@vpaid_date,@vremark,@vamount,@vinputter,GETDATE())

		   SET @vap_id =@vsysdoc 
	END

	SELECT @vap_id AS trancode

END
